{
  "message": "Use HTTPX 0.28.1’s explicit ASGI transport.",
  "rationale": "ASGITransport calls the supplied app in process while preserving headers, query strings, status validation, and JSON decoding. The async context manager closes the client; dependency pins remain unchanged.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "import httpx\n\n\nasync def fetch_json(app, path, headers=None):\n    async with httpx.AsyncClient(\n        transport=httpx.ASGITransport(app=app), base_url=\"http://test\", headers=headers\n    ) as client:\n        response = await client.get(path)\n        response.raise_for_status()\n        return response.json()\n",
      "delete": false
    }
  ]
}
